const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '../..');
const js = fs.readFileSync(path.join(root, 'assets/js/features/mapa/app.js'), 'utf8');
const css = fs.readFileSync(path.join(root, 'assets/css/features/mapa/app.css'), 'utf8');
const html = fs.readFileSync(path.join(root, 'mapa/index.html'), 'utf8');
const ok = (condition, message) => { if (!condition) throw new Error(message); };
ok(/async function removeCatalogLayerFromProject\(/.test(js), 'função de remoção de camada não encontrada');
ok(/enabled:\s*false/.test(js), 'remoção não desativa a preferência da camada');
ok(/auth\.saveLayerPreferences\(nextPrefs\)/.test(js), 'remoção não persiste preferências');
ok(/catalogMapLayers\.delete\(layerId\)/.test(js), 'camada não é removida do registro de mapa');
ok(/catalogLayerStates\.delete\(layerId\)/.test(js), 'estado da camada não é limpo');
ok(/map\.removeLayer\(existing\.leafletLayer\)/.test(js), 'Leaflet layer não é retirada do mapa');
ok(/hiddenCatalogLayerIds\.delete\(layerId\)/.test(js), 'estado oculto não é limpo para permitir re-adicionar');
ok(/removeButton\.textContent = 'Remover'/.test(js), 'botão Remover não foi adicionado ao card');
ok(/Você pode adicioná-la novamente em Adicionar camada/.test(js), 'feedback de readição não encontrado');
ok(/\.remove-catalog-layer/.test(css), 'estilo do botão remover ausente');
ok(/app-v21\.9\.0\.js\?v=[A-Za-z0-9._-]+/.test(html), 'cache-bust atual do mapa não foi encontrado');
console.log('PASS: camada oficial pode ser removida do mapa/projeto e permanece disponível para readição no catálogo.');
